mapper.select:
WITH daily_summary AS ( SELECT h.anls_ymd, v.fuel_cd, -- 미리 계산된 값들 CASE WHEN h.cb > 0 THEN h.cb / 1000.0 ELSE 0 END as cb_kg, COALESCE(h.idle_tm, 0) / 60.0 as idle_min, CASE WHEN h.opr_dstnc > 0 THEN h.opr_dstnc ELSE 0 END as distance, CASE WHEN h.fuel_usage > 0 AND h.opr_dstnc > 0 THEN h.opr_dstnc / h.fuel_usage ELSE NULL END as efficiency FROM anls_vhcl_opr_hstry h INNER JOIN cmm_vhcl_info v ON h.vhcl_sn = v.vhcl_sn WHERE 1=1 AND h.anls_ymd BETWEEN #{startDt} AND #{endDt}
AND h.ownr_nm = #{ownrNm}
) SELECT
anls_ymd as anls_dt,
DATE_FORMAT(anls_ymd, '%Y-%m') as anls_dt,
ROUND(SUM(cb_kg), 2) as cb, ROUND(SUM(idle_min), 2) as idle_tm, ROUND(AVG(CASE WHEN fuel_cd IN ('FU06', 'FU02') THEN efficiency END), 2) as avg_fu06, ROUND(AVG(CASE WHEN fuel_cd = 'FU04' THEN efficiency END), 2) as avg_fu04, ROUND(AVG(CASE WHEN fuel_cd = 'FU05' THEN efficiency END), 2) as avg_fu05, ROUND(SUM(distance), 2) as opr_dstnc FROM daily_summary
GROUP BY anls_ymd ORDER BY anls_ymd DESC
GROUP BY DATE_FORMAT(anls_ymd, '%Y-%m') ORDER BY DATE_FORMAT(anls_ymd, '%Y-%m') DESC

mapper.insert:
        INSERT INTO svc_stat_prvc_access (
            svc_nm,
            mbr_id,
            prvc_data,
            ip_addr
        ) VALUES (
            #{svcNm},
            #{currentUserId},
            (

	            SELECT JSON_ARRAYAGG(JSON_OBJECT(
			    	  'telno', telno))
		    	FROM svc_msg_rcvr_data
		    	WHERE 1=1

		    	        AND ownr_nm IN

		    	            #{ownr}




	            SELECT JSON_ARRAYAGG(JSON_OBJECT(
			    	  'telno', telno))
			    from svc_msg_rcptn_hstry 
			    where 1=1
			    	AND rcptn_type = #{rcptnType}
			    	AND (

		    	         ownr_nm IN

		    	            #{ownr}



						or ownr_nm is null

					)



			    	    	and ownr_nm = #{ownrNm}




				    	AND reg_dt >= CONCAT(#{startDt}, ' 00:00:00')
				      	AND reg_dt <= CONCAT(#{endDt}, ' 23:59:59') 

			    order by reg_dt desc
			    LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

		    ),
            #{ipAddr}
        )
